def transform(grid):
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]

    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v != background]
        if not cols:
            continue

        # Only extend a single uninterrupted stripe; fragmented rows are pattern details.
        if cols == list(range(cols[0], cols[-1] + 1)) and cols[-1] < len(row) - 1:
            for c in range(cols[-1] + 1, len(row)):
                out[r][c] = 1
    return out
